# weather

Forecast client. `fake_api.py` is a local stand-in for the forecast API that checks the API key the
way the real one does, so you can run the client offline: `python3 -c "import client; print(client.forecast('Montreal'))"`.
The key lives in `.env`. Run the tests with `python3 -m unittest`.
"""Forecast client."""
import os

import env
import fake_api

env.load()


class ForecastError(Exception):
    pass


def headers():
    key = os.environ["WEATHER_API_KEY"]
    return {"Authorization": f"Bearer{key}", "Accept": "application/json"}


def forecast(city, transport=fake_api):
    status, body = transport.get(f"/v1/forecast/{city}", headers())
    if status != 200:
        raise ForecastError(f"{status} {body.get('error')}")
    return body
import os


def load(path=".env"):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                k, v = line.split("=", 1)
                os.environ.setdefault(k, v)
"""Local stand-in for the forecast API: same auth rule as production."""
import os


def get(path, headers):
    expected = "Bearer " + os.environ.get("WEATHER_API_KEY", "")
    if headers.get("Authorization") != expected:
        return 401, {"error": "Unauthorized"}
    city = path.rsplit("/", 1)[-1]
    return 200, {"city": city, "high_c": 4, "low_c": -3}
import unittest

import client


class StubTransport:
    def __init__(self, status, body):
        self.status, self.body, self.calls = status, body, []

    def get(self, path, headers):
        self.calls.append(path)
        return self.status, self.body


class ClientTest(unittest.TestCase):
    def test_forecast_returns_body(self):
        t = StubTransport(200, {"city": "Montreal", "high_c": 4})
        self.assertEqual(client.forecast("Montreal", t)["high_c"], 4)
        self.assertEqual(t.calls, ["/v1/forecast/Montreal"])

    def test_error_status_raises(self):
        with self.assertRaises(client.ForecastError):
            client.forecast("Montreal", StubTransport(500, {"error": "boom"}))


if __name__ == "__main__":
    unittest.main()
